INSERT INTO questions (id, topic_id, question_text, question_type, options_json, correct_answer_json, explanation, difficulty, verified_source_id, status)
VALUES
    ('62000000-0000-0000-0001-000000000001', '41000000-0000-0000-0000-000000000001', 'An EC2 instance''s security group allows inbound HTTPS (port 443) from the internet. What must you add so the response traffic can return to the client?', 'single_choice', '["Nothing, because security groups are stateful", "An outbound security group rule for ports 1024-65535", "An outbound network ACL rule for port 443", "A NAT gateway in the subnet"]', '["Nothing, because security groups are stateful"]', 'Security groups are stateful: if inbound traffic is allowed, the response is automatically allowed out, regardless of outbound rules.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000002', '41000000-0000-0000-0000-000000000001', 'A subnet''s network ACL allows inbound TCP 443 from 0.0.0.0/0, and the instance''s security group allows HTTPS. Clients still time out. What is the most likely missing configuration?', 'single_choice', '["An outbound network ACL rule allowing ephemeral ports 1024-65535", "An inbound security group rule for port 80", "A VPC peering connection", "An Elastic IP on the network ACL"]', '["An outbound network ACL rule allowing ephemeral ports 1024-65535"]', 'Network ACLs are stateless, so return traffic must be explicitly allowed. Responses go to the client''s ephemeral port range.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000003', '41000000-0000-0000-0000-000000000001', 'What makes a subnet a public subnet in Amazon VPC?', 'single_choice', '["Its route table has a route to an internet gateway", "It has a CIDR block from a public IP range", "It contains a NAT gateway", "Its network ACL allows all inbound traffic"]', '["Its route table has a route to an internet gateway"]', 'A subnet is public when its associated route table sends internet-bound traffic (for example 0.0.0.0/0) to an internet gateway.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000004', '41000000-0000-0000-0000-000000000001', 'Which TWO are required for an EC2 instance in a VPC to be reachable from the internet over IPv4? (Choose two.)', 'multiple_choice', '["A public IPv4 address or Elastic IP address on the instance", "A route to an internet gateway in the subnet''s route table", "A NAT gateway in the same subnet", "A gateway VPC endpoint", "A private hosted zone in Route 53"]', '["A public IPv4 address or Elastic IP address on the instance", "A route to an internet gateway in the subnet''s route table"]', 'Inbound internet access needs a public address on the instance and a route to an internet gateway (plus security group and NACL rules allowing the traffic). A NAT gateway only provides outbound access.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000005', '41000000-0000-0000-0000-000000000001', 'Where must a NAT gateway be placed to give instances in private subnets outbound internet access?', 'single_choice', '["In a public subnet, with the private subnets'' routes pointing to it", "In each private subnet that needs internet access", "Attached directly to the internet gateway", "In any subnet, because NAT gateways are Regional"]', '["In a public subnet, with the private subnets'' routes pointing to it"]', 'A NAT gateway needs a route to the internet gateway, so it lives in a public subnet. Private subnets send 0.0.0.0/0 traffic to it.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000006', '41000000-0000-0000-0000-000000000001', 'Instances in a private subnet must read objects from Amazon S3 without traffic leaving the AWS network and without NAT gateway data processing charges. What should you use?', 'single_choice', '["A gateway VPC endpoint for Amazon S3", "A NAT gateway with a larger bandwidth limit", "VPC peering with the S3 service VPC", "An internet gateway with a restrictive network ACL"]', '["A gateway VPC endpoint for Amazon S3"]', 'A gateway endpoint adds a route to S3 in the route table, keeping traffic on the AWS network. Gateway endpoints for S3 have no additional charge.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000007', '41000000-0000-0000-0000-000000000001', 'VPC A is peered with VPC B, and VPC B is peered with VPC C. Can instances in VPC A reach VPC C through VPC B?', 'single_choice', '["No, VPC peering is not transitive", "Yes, if route tables in all three VPCs are updated", "Yes, if VPC B has a NAT gateway", "Only for traffic using IPv6"]', '["No, VPC peering is not transitive"]', 'VPC peering connections are not transitive. A and C need their own peering connection, or a hub such as AWS Transit Gateway.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000008', '41000000-0000-0000-0000-000000000001', 'A company needs to connect 30 VPCs and an on-premises network through a central hub, without managing many peering connections. Which service is designed for this?', 'single_choice', '["AWS Transit Gateway", "VPC peering", "An internet gateway", "A gateway VPC endpoint"]', '["AWS Transit Gateway"]', 'Transit Gateway acts as a regional hub that connects many VPCs and on-premises networks with central routing, instead of a full mesh of peering connections.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000009', '41000000-0000-0000-0000-000000000001', 'Which TWO statements about network ACLs are correct? (Choose two.)', 'multiple_choice', '["They are applied at the subnet level", "They can contain explicit deny rules", "They are stateful", "They are attached directly to EC2 instances", "They support allow rules only"]', '["They are applied at the subnet level", "They can contain explicit deny rules"]', 'Network ACLs apply to subnets, are stateless, and support both allow and deny rules evaluated in number order. Security groups are stateful and support allow rules only.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000010', '41000000-0000-0000-0000-000000000001', 'Private subnets in three Availability Zones use one NAT gateway in a single AZ. How should you remove this single point of failure?', 'single_choice', '["Create a NAT gateway in each AZ and route each AZ''s private subnets to the NAT gateway in the same AZ", "Increase the size of the existing NAT gateway", "Add a second internet gateway to the VPC", "Move the NAT gateway into a private subnet"]', '["Create a NAT gateway in each AZ and route each AZ''s private subnets to the NAT gateway in the same AZ"]', 'A NAT gateway is redundant within its own AZ only. One per AZ keeps outbound access working if an AZ fails and avoids cross-AZ data charges.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000011', '41000000-0000-0000-0000-000000000002', 'Data is rarely accessed, but when it is requested it must be available within milliseconds. Which storage class is the most cost-effective of these?', 'single_choice', '["S3 Standard-Infrequent Access", "S3 Standard", "S3 Glacier Deep Archive", "S3 Glacier Flexible Retrieval"]', '["S3 Standard-Infrequent Access"]', 'Standard-IA offers millisecond access with lower storage cost than Standard, in exchange for a retrieval fee. The Glacier Flexible Retrieval and Deep Archive classes take minutes to hours to restore.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000012', '41000000-0000-0000-0000-000000000002', 'Compliance records must be kept for 7 years and are almost never read. Retrieval within 12 hours is acceptable. Which option has the lowest storage cost?', 'single_choice', '["S3 Glacier Deep Archive", "S3 Standard", "S3 One Zone-Infrequent Access", "S3 Intelligent-Tiering"]', '["S3 Glacier Deep Archive"]', 'Glacier Deep Archive is the lowest-cost storage class, designed for long-term retention, with standard retrievals completing within 12 hours.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000013', '41000000-0000-0000-0000-000000000002', 'Which feature lets you recover an object that was accidentally overwritten or deleted?', 'single_choice', '["S3 Versioning", "S3 Transfer Acceleration", "S3 Inventory", "Requester Pays"]', '["S3 Versioning"]', 'With versioning, an overwrite creates a new version and a delete adds a delete marker, so earlier versions can be restored.', 1, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000014', '41000000-0000-0000-0000-000000000002', 'What is the simplest way to make sure no bucket in an AWS account can be made public by mistake?', 'single_choice', '["Turn on S3 Block Public Access at the account level", "Add a deny statement to every IAM user policy", "Enable default encryption on every bucket", "Enable S3 Versioning on every bucket"]', '["Turn on S3 Block Public Access at the account level"]', 'Account-level Block Public Access overrides bucket policies and ACLs that would grant public access, for all current and future buckets.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000015', '41000000-0000-0000-0000-000000000002', 'Objects should move to a cheaper storage class after 30 days and be deleted after one year, with no manual work. What should you configure?', 'single_choice', '["S3 Lifecycle rules", "S3 Event Notifications", "S3 Cross-Region Replication", "S3 Object Lock"]', '["S3 Lifecycle rules"]', 'Lifecycle rules automate transitions between storage classes and expiration (deletion) of objects based on age.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000016', '41000000-0000-0000-0000-000000000002', 'Which TWO are server-side encryption options for Amazon S3 objects? (Choose two.)', 'multiple_choice', '["SSE-S3 (keys managed by Amazon S3)", "SSE-KMS (keys in AWS Key Management Service)", "TLS encryption in transit", "IAM bucket policies", "S3 Object Lock"]', '["SSE-S3 (keys managed by Amazon S3)", "SSE-KMS (keys in AWS Key Management Service)"]', 'SSE-S3 and SSE-KMS encrypt data at rest on the server side. TLS protects data in transit; policies and Object Lock control access and retention, not encryption.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000017', '41000000-0000-0000-0000-000000000002', 'A static website stored in a private S3 bucket must be served worldwide over HTTPS, without making the bucket public. What should you use?', 'single_choice', '["Amazon CloudFront with origin access control (OAC)", "S3 static website hosting with a public bucket policy", "An Application Load Balancer in front of S3", "S3 Transfer Acceleration"]', '["Amazon CloudFront with origin access control (OAC)"]', 'OAC lets only your CloudFront distribution read the bucket, while CloudFront serves the content over HTTPS from edge locations. This is how SkillPulse itself is hosted.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000018', '41000000-0000-0000-0000-000000000002', 'Regulations require that log files cannot be deleted or changed for 5 years, even by administrators. Which feature meets this requirement?', 'single_choice', '["S3 Object Lock in compliance mode", "S3 Object Lock in governance mode", "S3 Versioning with MFA Delete only", "A bucket policy denying s3:DeleteObject"]', '["S3 Object Lock in compliance mode"]', 'Compliance mode prevents any user, including the root user, from deleting or overwriting a locked object version until the retention period ends. Governance mode can be bypassed with special permissions.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000019', '41000000-0000-0000-0000-000000000002', 'A user without AWS credentials needs to download one private object, and access should expire after 15 minutes. What is the simplest secure option?', 'single_choice', '["Generate a presigned URL for the object", "Make the object public for 15 minutes", "Create an IAM user and share its access keys", "Enable S3 static website hosting"]', '["Generate a presigned URL for the object"]', 'A presigned URL grants time-limited access to a specific object using the signer''s permissions, with no public access and no new credentials.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0001-000000000020', '41000000-0000-0000-0000-000000000002', 'Which TWO are requirements for S3 Cross-Region Replication? (Choose two.)', 'multiple_choice', '["Versioning enabled on the source bucket", "Versioning enabled on the destination bucket", "Both buckets in the same Region", "A public destination bucket", "S3 Transfer Acceleration enabled"]', '["Versioning enabled on the source bucket", "Versioning enabled on the destination bucket"]', 'Replication requires versioning on both source and destination buckets, plus an IAM role that S3 can assume to replicate objects.', 3, '60000000-0000-0000-0000-000000000001', 'published')
